package com.example.guidego;

import android.os.Bundle;

import androidx.activity.EdgeToEdge;
import androidx.appcompat.app.AppCompatActivity;
import androidx.core.graphics.Insets;
import androidx.core.view.ViewCompat;
import androidx.core.view.WindowInsetsCompat;

public class MainActivity extends AppCompatActivity {

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        EdgeToEdge.enable(this);
        setContentView(R.layout.activity_main);
        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main), (v, insets) -> {
            Insets systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars());
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom);
            return insets;
        });
    }
}

package com.example.guidego;

import android.os.Bundle;

import androidx.appcompat.app.AppCompatActivity;
import androidx.fragment.app.Fragment;

import com.example.guidego.databinding.ActivityMainBinding;
import com.example.guidego.ui.booking.BookingFragment;
import com.example.guidego.ui.cart.CartFragment;
import com.example.guidego.ui.home.HomeFragment;
import com.example.guidego.ui.profile.ProfileFragment;
import com.example.guidego.ui.search.SearchFragment;

public class MainActivity extends AppCompatActivity {

    private ActivityMainBinding binding;
    private HomeFragment homeFragment;
    private SearchFragment searchFragment;
    private CartFragment cartFragment;
    private BookingFragment bookingFragment;
    private ProfileFragment profileFragment;
    private Fragment activeFragment;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        binding = ActivityMainBinding.inflate(getLayoutInflater());
        setContentView(binding.getRoot());
        initFragments();
        setupBottomNav();
    }

    private void initFragments() {
        homeFragment = new HomeFragment();
        searchFragment = new SearchFragment();
        cartFragment = new CartFragment();
        bookingFragment = new BookingFragment();
        profileFragment = new ProfileFragment();

        getSupportFragmentManager().beginTransaction()
                .add(R.id.fragment_container, homeFragment, "home")
                .add(R.id.fragment_container, searchFragment, "search").hide(searchFragment)
                .add(R.id.fragment_container, cartFragment, "cart").hide(cartFragment)
                .add(R.id.fragment_container, bookingFragment, "booking").hide(bookingFragment)
                .add(R.id.fragment_container, profileFragment, "profile").hide(profileFragment)
                .commit();
        activeFragment = homeFragment;
    }

    private void setupBottomNav() {
        binding.bottomNav.setOnItemSelectedListener(item -> {
            Fragment selected = null;
            int id = item.getItemId();
            if (id == R.id.nav_home) selected = homeFragment;
            else if (id == R.id.nav_search) selected = searchFragment;
            else if (id == R.id.nav_cart) selected = cartFragment;
            else if (id == R.id.nav_bookings) selected = bookingFragment;
            else if (id == R.id.nav_profile) selected = profileFragment;

            if (selected != null && selected != activeFragment) {
                getSupportFragmentManager().beginTransaction()
                        .hide(activeFragment).show(selected).commit();
                activeFragment = selected;
            }
            return true;
        });
    }

    public void navigateToCart() { binding.bottomNav.setSelectedItemId(R.id.nav_cart); }
    public void navigateToBookings() { binding.bottomNav.setSelectedItemId(R.id.nav_bookings); }
}

package com.example.guidego.utils;

import android.content.Context;
import android.content.SharedPreferences;
import android.util.Base64;
import android.util.Log;

import org.json.JSONObject;

public class TokenManager {
    private static final String TAG = "TokenManager";
    private final SharedPreferences prefs;

    public TokenManager(Context context) {
        prefs = context.getSharedPreferences(Constants.PREF_NAME, Context.MODE_PRIVATE);
    }

    public void saveToken(String token) {
        prefs.edit().putString(Constants.KEY_TOKEN, token).apply();
        decodeAndSaveClaims(token);
    }

    public String getToken() {
        return prefs.getString(Constants.KEY_TOKEN, null);
    }

    public boolean isLoggedIn() {
        String token = getToken();
        return token != null && !token.isEmpty() && !isTokenExpired(token);
    }

    public void clearToken() {
        prefs.edit().clear().apply();
    }

    public String getUserId() {
        return prefs.getString(Constants.KEY_USER_ID, "");
    }

    public String getUserEmail() {
        return prefs.getString(Constants.KEY_USER_EMAIL, "");
    }

    public String getUserName() {
        return prefs.getString(Constants.KEY_USER_NAME, "Người dùng");
    }

    public String getUserRole() {
        return prefs.getString(Constants.KEY_USER_ROLE, Constants.ROLE_TOURIST);
    }

    public boolean isTourist() {
        return Constants.ROLE_TOURIST.equals(getUserRole());
    }

    public boolean isGuide() {
        return Constants.ROLE_GUIDE.equals(getUserRole());
    }

    public boolean isAdmin() {
        return Constants.ROLE_ADMIN.equals(getUserRole());
    }

    private void decodeAndSaveClaims(String token) {
        try {
            String[] parts = token.split("\\.");
            if (parts.length < 2) return;

            // Add padding if needed
            String payload = parts[1];
            int mod4 = payload.length() % 4;
            if (mod4 != 0) payload += "====".substring(mod4);

            byte[] decodedBytes = Base64.decode(payload, Base64.URL_SAFE | Base64.NO_PADDING);
            String jsonStr = new String(decodedBytes, "UTF-8");
            JSONObject json = new JSONObject(jsonStr);

            // Try multiple claim name formats (ASP.NET Core JWT)
            String userId = json.optString("nameid",
                    json.optString("sub",
                            json.optString("http://schemas.xmlsoap.org/ws/2005/05/identity/claims/nameidentifier", "")));

            String role = json.optString("role",
                    json.optString("http://schemas.microsoft.com/ws/2008/06/identity/claims/role", Constants.ROLE_TOURIST));

            String email = json.optString("email",
                    json.optString("http://schemas.xmlsoap.org/ws/2005/05/identity/claims/emailaddress", ""));

            String name = json.optString("unique_name",
                    json.optString("name", json.optString("given_name", "")));

            prefs.edit()
                    .putString(Constants.KEY_USER_ID, userId)
                    .putString(Constants.KEY_USER_ROLE, role)
                    .putString(Constants.KEY_USER_EMAIL, email)
                    .putString(Constants.KEY_USER_NAME, name)
                    .apply();

            Log.d(TAG, "Decoded JWT: userId=" + userId + ", role=" + role + ", email=" + email);
        } catch (Exception e) {
            Log.e(TAG, "Failed to decode JWT", e);
        }
    }

    private boolean isTokenExpired(String token) {
        try {
            String[] parts = token.split("\\.");
            if (parts.length < 2) return true;
            String payload = parts[1];
            int mod4 = payload.length() % 4;
            if (mod4 != 0) payload += "====".substring(mod4);
            byte[] decodedBytes = Base64.decode(payload, Base64.URL_SAFE | Base64.NO_PADDING);
            String jsonStr = new String(decodedBytes, "UTF-8");
            JSONObject json = new JSONObject(jsonStr);
            long exp = json.optLong("exp", 0);
            if (exp == 0) return false;
            long now = System.currentTimeMillis() / 1000;
            return now >= exp;
        } catch (Exception e) {
            return false;
        }
    }
}

